//! Area URL components share the original hyperlink parser.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><area id=area href=https://user:pass@example.test:8443/start?q=1#old><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://area-url.test/path/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn area_url_canonical_component_descriptors_and_initial_projection(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),names=['origin','protocol','username','password','host','hostname','port','pathname','search','hash'],values=['https://example.test:8443','https:','user','pass','example.test:8443','example.test','8443','/start','?q=1','#old'];for(var i=0;i<names.length;i++){var name=names[i],a=Object.getOwnPropertyDescriptor(HTMLAreaElement.prototype,name);if(!a||!a.enumerable||!a.configurable||a.get.length||a.get.name!=='get '+name||Object.hasOwn(x,name)||a.get.call(x)!==values[i]||x[name]!==values[i])throw 'canonical component getter';if(i===0){if(a.set!==undefined)throw 'readonly origin';}else if(a.set.length!==1||a.set.name!=='set '+name)throw 'canonical component setter';}"#);}
#[test]
fn area_url_native_component_writes_update_actual_href_and_records(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),attr=x.getAttributeNode('href'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.protocol='http:';x.username='next';x.password='secret';x.hostname='other.test';x.port='8080';x.pathname='/a b';x.search='q=\u00e4';x.hash='part';if(x.href!=='http://next:secret@other.test:8080/a%20b?q=%C3%A4#part'||attr.value!==x.href||x.getAttributeNode('href')!==attr)throw 'shared component serialization';var records=watch.takeRecords();if(records.length!==8||records[0].attributeName!=='href'||records[0].oldValue!=='https://user:pass@example.test:8443/start?q=1#old')throw 'actual href observer records';x.host='last.test:90';if(x.host!=='last.test:90'||x.hostname!=='last.test'||x.port!=='90'||x.origin!=='http://last.test:90')throw 'host setter';var before=x.href;watch.takeRecords();x.port='70000';if(x.href!==before||watch.takeRecords().length)throw 'invalid port no-op';"#);}
#[test]
fn area_url_inert_reentry_current_base_missing_and_brand(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument(''),base=owner.createElement('base');base.setAttribute('href','https://first.test/path/');owner.head.appendChild(base);var x=owner.createElement('area');x.port='10';if(x.href!==''||x.protocol!==':'||x.origin!==''||x.getAttribute('href')!==null)throw 'missing component no-op';x.href='leaf';var calls=0;x.search={toString:function(){calls++;base.setAttribute('href','https://second.test/current/');return 'q=\u00e4';}};if(calls!==1||x.href!=='https://second.test/current/leaf?q=%C3%A4'||x.search!=='?q=%C3%A4')throw 'current base after conversion';var a=Object.getOwnPropertyDescriptor(HTMLAreaElement.prototype,'hash'),caught=false;try{a.set.call(owner.createElement('a'),{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls!==1)throw 'component area brand before conversion';"#);}

#[test]
fn area_url_all_component_brands_readonly_origin_and_author_override(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),P=HTMLAreaElement.prototype,names=['origin','protocol','username','password','host','hostname','port','pathname','search','hash'],calls=0;for(var name of names){var a=Object.getOwnPropertyDescriptor(P,name),anchor=Object.getOwnPropertyDescriptor(HTMLAnchorElement.prototype,name),caught=false;try{anchor.get.call(x);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'anchor saved getter brand';for(var bad of [{},Object.create(P),document.body,document.createElement('a'),document.createElementNS('urn:foreign','area')]){caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'area getter brand';if(a.set){caught=false;try{a.set.call(bad,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'setter brand precedes conversion';}}}var old=x.origin;x.origin={toString:function(){calls++;return 'https://bad.test';}};if(calls||x.origin!==old||Object.hasOwn(x,'origin'))throw 'readonly origin without conversion';var a=Object.getOwnPropertyDescriptor(P,'pathname');Object.defineProperty(x,'pathname',{value:'author',writable:true,configurable:true});a.set.call(x,'/canonical');if(x.pathname!=='author'||a.get.call(x)!=='/canonical')throw 'saved component authority';delete x.pathname;if(x.pathname!=='/canonical')throw 'restored inherited component';"#);
}
#[test]
fn area_url_conversion_reentry_abrupt_symbols_and_no_navigation(){
 let(mut d,mut f,mut p)=fixture();let location=p.state.location.as_ref().map(|v|v.source.display());run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),attr=x.getAttributeNode('href'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});var calls=0;x.pathname={toString:function(){calls++;attr.value='https://new.test/base?old#part';return '/a\ud800Z';}};var records=watch.takeRecords();if(calls!==1||x.href!=='https://new.test/a%EF%BF%BDZ?old#part'||records.length!==2||records[1].oldValue!=='https://new.test/base?old#part'||attr.value!==x.href)throw 'current URL after once conversion';var marker={},caught;try{x.hash={toString:function(){x.href='https://effect.test/';throw marker;}};}catch(e){caught=e;}if(caught!==marker||x.href!=='https://effect.test/'||watch.takeRecords().length!==1)throw 'abrupt author effects';for(var name of ['protocol','username','password','host','hostname','port','pathname','search','hash']){caught=false;try{x[name]=Symbol('URL');}catch(e){caught=e instanceof TypeError;}if(!caught||watch.takeRecords().length||x.href!=='https://effect.test/')throw 'symbol before mutation';}"#);assert_eq!(p.state.location.as_ref().map(|v|v.source.display()),location);assert!(p.state.navigation.is_none());
}
#[test]
fn area_url_component_writers_refuse_atomically_and_recover(){
 for inert in [false,true]{for name in ["protocol","username","password","host","hostname","port","pathname","search","hash"]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','area');"}else{"var x=document.getElementById('area');"});run(&mut d,&mut f,&mut p,"x.href='http://u:p@host.test:9/x';var attr=x.getAttributeNode('href'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");let value=match name{"protocol"=>"https:","host"=>"long-component-host.test:65535","hostname"=>"long-component-host.test","port"=>"65535",_=>"long-component-value-with-extra-storage"};let code=format!("x.{name}='{value}';");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(&code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("time")||e.contains("bound"),"{inert}/{name}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(attr.value!=='http://u:p@host.test:9/x'||watch.takeRecords().length)throw 'atomic component refusal';");run(&mut d,&mut f,&mut p,&code);run(&mut d,&mut f,&mut p,"var records=watch.takeRecords();if(records.length!==1||records[0].oldValue!=='http://u:p@host.test:9/x'||records[0].attributeName!=='href'||x.getAttributeNode('href')!==attr||attr.value!==x.href)throw 'fresh component recovery';");
 }}}
}
#[test]
fn area_url_reads_pay_shared_parser_bounds_without_mutation(){
 for inert in [false,true]{for name in ["origin","protocol","username","password","host","hostname","port","pathname","search","hash"]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','area');x.href='https://u:p@example.test:8443/path?q=1#old';"}else{"var x=document.getElementById('area');"});let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("area handle")};let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.limits.host.string_bytes=1,3=>p.state.execution_deadline=Some(Instant::now()),_=>p.state.retained_limit=p.state.retained};let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.area_url_get(object,name);if mode==4{assert!(result.is_ok());}else{let e=result.unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("time")||e.contains("bound"),"{e}");}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.area_url_get(object,name).is_ok());}}}
}
#[test]
fn area_url_saved_child_origin_precedes_component_conversion_and_recovers(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLAreaElement.prototype,'pathname'),calls=0;if(a.get.call(x)!=='/start')throw 'captured component';"#);p.set_location(&crate::navigation::address("https://other-url.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);for code in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return '/bad';}});"]{p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);}p.set_location(&crate::navigation::address("https://area-url.test/path/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin before component conversion';a.set.call(x,'/recovered');if(a.get.call(x)!=='/recovered')throw 'fresh origin recovery';");
}
#[test]
fn area_url_existing_unsupported_schemes_refuse_atomically_and_invalid_missing_noops(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.href='mailto:user@example.test';watch.takeRecords();");
 for code in ["x.pathname='/ignored';","x.host='ignored.test';","x.port='80';","x.origin;"]{let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("only HTTP(S)"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"if(x.getAttribute('href')!=='mailto:user@example.test'||watch.takeRecords().length)throw 'unsupported scheme atomic refusal';");}
 run(&mut d,&mut f,&mut p,r#"x.href='http://[';watch.takeRecords();x.hash='ignored';x.pathname='/ignored';if(x.href!=='http://['||watch.takeRecords().length)throw 'invalid no-ops';x.removeAttribute('href');watch.takeRecords();for(var name of ['protocol','username','password','host','hostname','port','pathname','search','hash'])x[name]='ignored';if(x.href!==''||x.getAttribute('href')!==null||watch.takeRecords().length)throw 'missing no-ops';x.href='https://recovery.test/path';x.hash='ok';if(x.href!=='https://recovery.test/path#ok')throw 'fresh supported scheme recovery';"#);
}
